import{_ as r,a as e,b as i,c as o,d as t}from"./chunks/star-of-india.DFvd32t6.js";import{_ as s,o as l,c as n,a4 as d}from"./chunks/framework.BybBnFXO.js";const u=JSON.parse('{"title":"传奇宝石","description":"","frontmatter":{"title":"传奇宝石","gallery":"legendary-stones"},"headers":[],"relativePath":"zh/gallery/legendary-stones.md","filePath":"zh/gallery/legendary-stones.md","lastUpdated":1788135225000}'),c={name:"zh/gallery/legendary-stones.md"};function _(m,a,p,h,k,g){return l(),n("div",null,[...a[0]||(a[0]=[d('<h1 id="传奇宝石" tabindex="-1">传奇宝石 <a class="header-anchor" href="#传奇宝石" aria-label="Permalink to &quot;传奇宝石&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>少数宝石因尺寸、颜色或历史而名垂青史——Hope 蓝钻、Koh-i-Noor、 Cullinan 系列、Regent 钻石、Star of India。它们的故事与它们本身一样珍贵。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>Hope 蓝钻 (45.52 ct)：世界最著名蓝钻，切磨自法国王室蓝钻，现藏史密森尼。</li><li>Koh-i-Noor (105.6 ct)：莫卧儿&quot;光之山&quot;，现为英国王冠上石。</li><li>Cullinan I (530.2 ct)：最大顶级切割钻石，&quot;非洲之星&quot;，镶嵌英王权杖。</li><li>Regent 钻石 (140.6 ct)：曾镶路易十五王冠，现存卢浮宫。</li><li>Star of India (563 ct)：世界最大星光蓝宝石，现藏美国自然史博物馆。</li></ul><h2 id="图像档案" tabindex="-1">图像档案 <a class="header-anchor" href="#图像档案" aria-label="Permalink to &quot;图像档案&quot;">​</a></h2><p>下列图片对应本页列出的五件传奇宝石；图片均已本地收录，来源与授权见<a href="./../../image-credits.html">图片署名页</a>。</p><div class="maison-work-grid legendary-stones-grid"><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Hope_Diamond_Smithsonian.jpg" target="_blank" rel="noreferrer"><img src="'+r+'" alt="Hope 蓝钻" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>45.52 ct · 蓝钻</span></div><h3>Hope 蓝钻</h3><p>史密森尼展柜 · 法国王室蓝钻前身</p><p class="maison-work-card__source"><a href="https://commons.wikimedia.org/wiki/File:Hope_Diamond_Smithsonian.jpg" target="_blank" rel="noreferrer">查看原始文件页</a></p></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Kohinoor.jpg" target="_blank" rel="noreferrer"><img src="'+e+'" alt="Koh-i-Noor 光之山" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>105.6 ct · 历史钻石</span></div><h3>Koh-i-Noor 光之山</h3><p>历史插图 · 原始镶嵌状态</p><p class="maison-work-card__source"><a href="https://commons.wikimedia.org/wiki/File:Kohinoor.jpg" target="_blank" rel="noreferrer">查看原始文件页</a></p></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Cullinan_Diamond_and_some_of_its_cuts_-_copy.jpg" target="_blank" rel="noreferrer"><img src="'+i+'" alt="Cullinan I 非洲之星" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>530.2 ct · D 色钻石</span></div><h3>Cullinan I 非洲之星</h3><p>非洲之星 · 英王权杖</p><p class="maison-work-card__source"><a href="https://commons.wikimedia.org/wiki/File:Cullinan_Diamond_and_some_of_its_cuts_-_copy.jpg" target="_blank" rel="noreferrer">查看原始文件页</a></p></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Diamant_le_R%C3%A9gent_%28Louvre%29.jpg" target="_blank" rel="noreferrer"><img src="'+o+'" alt="Regent 钻石" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>140.6 ct · 历史钻石</span></div><h3>Regent 钻石</h3><p>路易十五王冠 · 卢浮宫馆藏</p><p class="maison-work-card__source"><a href="https://commons.wikimedia.org/wiki/File:Diamant_le_R%C3%A9gent_%28Louvre%29.jpg" target="_blank" rel="noreferrer">查看原始文件页</a></p></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Star_Of_India_Gem2.jpg" target="_blank" rel="noreferrer"><img src="'+t+'" alt="Star of India 印度之星" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>563 ct · 星光蓝宝石</span></div><h3>Star of India 印度之星</h3><p>美国自然史博物馆馆藏</p><p class="maison-work-card__source"><a href="https://commons.wikimedia.org/wiki/File:Star_Of_India_Gem2.jpg" target="_blank" rel="noreferrer">查看原始文件页</a></p></div></article></div><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>作品</th><th>详情</th><th>备注</th></tr></thead><tbody><tr><td>Hope Diamond</td><td>45.52 ct, blue</td><td>—</td></tr><tr><td>Cullinan I</td><td>530.2 ct, D colour</td><td>—</td></tr><tr><td>Star of India</td><td>563 ct, star sapphire</td><td>—</td></tr></tbody></table><p><em>详见<a href="./intro.html">画廊总览</a>。</em></p>',11)])])}const b=s(c,[["render",_]]);export{u as __pageData,b as default};
